create or replace function menus.adopt_prospect(p_prospect_id uuid,p_organization_id uuid,p_unit_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_count integer; begin if not exists(select 1 from core.units u where u.id=p_unit_id and u.organization_id=p_organization_id) then raise exception 'INVALID_UNIT_SCOPE'; end if; update menus.menus set organization_id=p_organization_id,unit_id=p_unit_id,updated_at=now() where prospect_id=p_prospect_id and (unit_id is null or unit_id=p_unit_id); get diagnostics v_count=row_count; return jsonb_build_object('adoptedMenus',v_count); end $$;
revoke all on function menus.adopt_prospect(uuid,uuid,uuid) from public,anon,authenticated; grant execute on function menus.adopt_prospect(uuid,uuid,uuid) to service_role;
